installation.script:
#!/bin/bash
# r2-uploader installation script
mkdir -p /mnt/server/data

if [ ! -f /mnt/server/.env ]; then
cat << 'EOF' > /mnt/server/.env
PORT=${SERVER_PORT}
R2_ACCOUNT_ID=${R2_ACCOUNT_ID}
R2_ACCESS_KEY_ID=${R2_ACCESS_KEY_ID}
R2_SECRET_ACCESS_KEY=${R2_SECRET_ACCESS_KEY}
R2_BUCKET_NAME=${R2_BUCKET_NAME}
R2_ROOT_FOLDER=${R2_ROOT_FOLDER}
R2_PUBLIC_DOMAIN=${R2_PUBLIC_DOMAIN}
APP_URL=${APP_URL}
ADMIN_KEY=${ADMIN_KEY}
SQLITE_PATH=data/data.db
KEY_PREFIX=sk_vhming_
EOF
fi

if [ -n "${DOWNLOAD_URL}" ]; then
  echo "Downloading binary from ${DOWNLOAD_URL}..."
  curl -sSL -o /mnt/server/${SERVER_BINARY} "${DOWNLOAD_URL}"
  chmod +x /mnt/server/${SERVER_BINARY}
fi

echo "-----------------------------------------"
echo "Installation completed."
echo "Please ensure '${SERVER_BINARY}' is present before starting."
echo "-----------------------------------------"
